const items = $input.all();

function classifyDecision(decision) {
  switch (decision) {
    case "DEFER_ORIGIN_LOW_SIGNAL":
      return {
        category: "pass_through_no_origin",
        status: "not_admitted",
        severity: "low",
      };

    case "ORIGIN_CANDIDATE":
      return {
        category: "origin_candidate",
        status: "admitted",
        severity: "normal",
      };

    case "BOUNDARY_SECRET_REQUEST":
      return {
        category: "credential_boundary",
        status: "blocked",
        severity: "high",
      };

    case "BOUNDARY_MANIPULATION_REQUEST":
      return {
        category: "manipulation_boundary",
        status: "blocked",
        severity: "high",
      };

    case "SAFE_CREDENTIAL_GUIDANCE":
      return {
        category: "safe_credential_guidance",
        status: "safe_guidance",
        severity: "medium",
      };

    case "ASK_CLARIFICATION_SENSITIVE":
      return {
        category: "sensitive_clarification",
        status: "clarify",
        severity: "medium",
      };

    case "MONITOR_OR_ASK_CLARIFICATION":
      return {
        category: "monitor_or_clarify",
        status: "monitor",
        severity: "medium",
      };

    default:
      return {
        category: "unknown",
        status: "review",
        severity: "medium",
      };
  }
}

return items.map((item) => {
  const response = item.json || {};

  const policy = response.input_policy || {};
  const result = response.result || {};
  const app = response.application_response || {};
  const metadata = policy.metadata || {};

  const decision = policy.decision || result.decision || "UNKNOWN";
  const mapped = classifyDecision(decision);

  return {
    json: {
      ok: true,
      source: "ACA Runtime /policy-evaluate",
      method: response.method || "measure_only + Input Policy Overlay + ACA artifact projection",
      llm_generation_used: response.llm_generation_used === true,

      decision,
      category: mapped.category,
      status: mapped.status,
      severity: mapped.severity,

      message: app.message || policy.reason || response.summary || "",
      summary: response.summary || "",

      should_call_llm: app.should_call_llm === true,
      boundary_applied: policy.boundary_applied === true || app.boundary_applied === true,
      origin_allowed: policy.origin_allowed === true,
      state_mutation_allowed: policy.state_mutation_allowed === true,

      semantic_field: result.semantic_field || metadata.F || null,
      context_field: metadata.C || null,
      principle_field: metadata.P || null,
      transversal_field: metadata.T || null,

      criterion_confidence: result.criterion_confidence ?? null,
      trajectory_state: result.trajectory_state || null,
      ambiguity: result.ambiguity || null,

      metadata,
      explanation: response.explanation || [],
    },
  };
});
